public final class FastDirectBufferRegistry {
    private final long[] keys;
    private final Object[] values;
    private final int capacityMask;

    public FastDirectBufferRegistry(int capacity) {
        int cap = Integer.highestOneBit(capacity) << 1;
        this.keys = new long[cap];
        this.values = new Object[cap];
        this.capacityMask = cap - 1;
    }

    private int hash(long key) {
        long h = key ^ (key >>> 30);
        h *= 0xbf58476d1ce4e5b9L;
        h ^= (h >>> 27);
        h *= 0x94d049bb133111ebL;
        return (int)(h ^ (h >>> 31));
    }

    public void put(long address, Object buffer) {
        int idx = hash(address) & capacityMask;
        while (keys[idx] != 0L && keys[idx] != address) {
            idx = (idx + 1) & capacityMask;
        }
        keys[idx] = address;
        values[idx] = buffer;
    }
}
